      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle supplies the adjustment condition, weakening consequence and prospective status."
    }
  },
  "signal_basis": {
    "component_id": "C043_signal_basis",
    "value": "An initially observed version association disappears after accounting for trace coverage or workload in the comparative analysis.",
    "scope": "Assumed occurrence of the proposed observation, with sensitivity comparisons by version and workload; confounding and measurement distortions remain recognized limitations.",
    "provenance": {
      "refs": [
        {"source_id": "P020", "role": "SUPPORT"},
        {"source_id": "P021", "role": "SUPPORT"},
        {"source_id": "P011", "role": "SUPPORT"},
